// ── Cryptography with Node.js built-in 'crypto' module ───────────
import {
  createCipheriv,
  createDecipheriv,
  randomBytes,
  generateKeyPairSync,
  createDiffieHellman,
  createSign,
  createVerify,
} from 'node:crypto';

// ── 1. AES-256-GCM: authenticated symmetric encryption ──────────
function aesEncrypt(plaintext, key) {
  const iv = randomBytes(12);  // 96-bit nonce for GCM — must be unique per (key, message) pair
  const cipher = createCipheriv('aes-256-gcm', key, iv);
  const encrypted = Buffer.concat([
    cipher.update(plaintext, 'utf8'),
    cipher.final(),
  ]);
  const authTag = cipher.getAuthTag(); // 128-bit integrity tag
  return {
    iv: iv.toString('hex'),
    ciphertext: encrypted.toString('hex'),
    authTag: authTag.toString('hex'),
  };
}

function aesDecrypt({ iv, ciphertext, authTag }, key) {
  const decipher = createDecipheriv(
    'aes-256-gcm',
    key,
    Buffer.from(iv, 'hex')
  );
  // setAuthTag triggers integrity verification on final() — throws if tampered
  decipher.setAuthTag(Buffer.from(authTag, 'hex'));
  return Buffer.concat([
    decipher.update(Buffer.from(ciphertext, 'hex')),
    decipher.final(),   // throws if authTag invalid
  ]).toString('utf8');
}

const key256 = randomBytes(32);  // 256-bit symmetric key
const encrypted = aesEncrypt('Hello, secure world!', key256);
console.log('Encrypted payload:', encrypted);
console.log('Decrypted:', aesDecrypt(encrypted, key256)); // Hello, secure world!

// ── 2. Diffie-Hellman: shared secret without transmitting secret ─
// Use well-known MODP group 14 (2048-bit) from RFC 3526 — safer than custom params
const alice = createDiffieHellman(2048);
const alicePublicKey = alice.generateKeys();

const bob = createDiffieHellman(alice.getPrime(), alice.getGenerator());
const bobPublicKey = bob.generateKeys();

const aliceShared = alice.computeSecret(bobPublicKey);
const bobShared   = bob.computeSecret(alicePublicKey);
console.log('DH secrets match:', aliceShared.equals(bobShared)); // true
// In practice: derive an AES key from this shared secret using HKDF

// ── 3. RSA-2048 key pair + digital signature ────────────────────
const { publicKey, privateKey } = generateKeyPairSync('rsa', {
  modulusLength: 2048,
  publicKeyEncoding:  { type: 'spki',  format: 'pem' },
  privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
});

const message = Buffer.from('Authenticate this message');
const sign = createSign('SHA256');
sign.update(message);
const signature = sign.sign(privateKey); // Sign with private key

const verify = createVerify('SHA256');
verify.update(message);
console.log('Signature valid:', verify.verify(publicKey, signature)); // true

// Tampering detection
const tampered = Buffer.from('Authenticate this TAMPERED message');
const verify2 = createVerify('SHA256');
verify2.update(tampered);
console.log('Tampered valid:', verify2.verify(publicKey, signature)); // false

// ── Security level comparison: symmetric vs RSA vs ECC ───────
//
// Security Level │ Symmetric (AES) │ RSA Key Size  │ ECC Key Size
// ───────────────┼─────────────────┼───────────────┼──────────────
// 80-bit         │ AES-80 (retired)│ RSA-1024 (broken!) | P-160
// 112-bit        │ AES-112         │ RSA-2048      │ P-224
// 128-bit        │ AES-128         │ RSA-3072      │ P-256 / X25519
// 192-bit        │ AES-192         │ RSA-7680      │ P-384
// 256-bit        │ AES-256         │ RSA-15360     │ P-521
//
// Key takeaway: ECC-256 ≈ AES-128 ≈ RSA-3072 in security strength.
// ECC keys are 12x shorter than RSA at equivalent security.

// ── CIA triad in cryptographic primitives ────────────────────
const CIA = {
  Confidentiality: [
    'AES-256-GCM (symmetric, bulk data)',
    'RSA-OAEP or ECDH (key transport/exchange)',
    'ChaCha20-Poly1305 (mobile/low-power)',
  ],
  Integrity: [
    'AEAD auth tag (AES-GCM, ChaCha20-Poly1305)',
    'HMAC-SHA256 (separate MAC)',
    'SHA-256 checksum (weaker: no key)',
  ],
  Authenticity: [
    'ECDSA with P-256 (TLS certificates)',
    'Ed25519 (SSH, Signal, modern TLS)',
    'RSA-PSS (legacy TLS)',
  ],
};

// ── Key exchange comparison ───────────────────────────────────
const KEY_EXCHANGE = {
  'RSA key transport': {
    mechanism:      'Client encrypts AES key with server RSA public key',
    forwardSecrecy: false,  // past sessions broken if private key leaked
    tlsVersion:     'TLS 1.2 (removed from TLS 1.3)',
  },
  'ECDHE (X25519)': {
    mechanism:      'Ephemeral key pairs per session, HKDF-derived session keys',
    forwardSecrecy: true,   // ephemeral keys discarded after handshake
    tlsVersion:     'TLS 1.2 + TLS 1.3 (mandatory in TLS 1.3)',
  },
};

// ── Password hashing: right vs wrong ─────────────────────────
import { createHash } from 'node:crypto';

// WRONG: fast hash, no salt — trivially brutable
function insecurePasswordHash(password) {
  return createHash('sha256').update(password).digest('hex');
  // 'password123' -> same hash for every user, rainbow tables work
}

