// ── Constant-time comparison (prevents timing attacks) ────────
import { timingSafeEqual } from 'node:crypto';

function safeCompare(a, b) {
  // Regular === leaks information: returns early on first mismatch
  // timingSafeEqual always takes the same time regardless of where strings differ
  const bufA = Buffer.from(a);
  const bufB = Buffer.from(b);
  if (bufA.length !== bufB.length) return false; // length still leaks, but acceptable for fixed-length tokens
  return timingSafeEqual(bufA, bufB);
}
